def construct_sequence(n):
    if n == 1:
        return "1337"

    result = []
    while n > 0:
        if n % 7 == 0:
            result.append("7")
            n //= 7
        elif n % 3 == 0:
            result.append("3")
            n //= 3
        else:
            result.append("1")
            n -= 1

    return "".join(result[::-1])

