        return "1337"
    base = "1337"
    result = base * (n // 4 + 1)
    remainder = n % 4
    if remainder == 1:
        result += "1"
    elif remainder == 2:
        result += "13"
    elif remainder == 3:
        result += "133"
    return result[:len(base) * (n // 4 + 1)]

